import math
def ultrapower_gcd(f, g):
    return lambda i: math.gcd(f(i), g(i))

def standard_part(f, bound, is_large, N=10000):
    for m in range(bound + 1):
        eq_set = {i for i in range(N) if f(i) == m}
        if is_large(eq_set): return m
    return None

def overspill_witness(P, max_n=1000):
    def f(i):
        best = 0
        for n in range(min(i+1, max_n)):
            if P(i, n): best = n
            else: break
        return best
    return f
